def magic_square_test(matrix):
    n = len(matrix)
    if n == 0:
        return False

    # Calculate the sum of the first row to use as a reference
    ref_sum = sum(matrix[0])

    # Check rows and columns for equal sums
    for i in range(n):
        if sum(matrix[i]) != ref_sum or sum([matrix[j][i] for j in range(n)]) != ref_sum:
            return False

    # Check diagonals for equal sums
    if sum([matrix[i][i] for i in range(n)]) != ref_sum or sum([matrix[i][n-i-1] for i in range(n)]) != ref_sum:
        return False

    return True

def reverse_vowels(s):
    vowels = 'aeiouAEIOU'
    s_list = list(s)
    left, right = 0, len(s) - 1

    while left < right:
        if s_list[left] not in vowels:
            left += 1
        elif s_list[right] not in vowels:
            right -= 1
        else:
            s_list[left], s_list[right] = s_list[right], s_list[left]
